var doc = Document;
return Connector.WithTransaction(doc, () => {
  // Setup: one wall in a group, placed twice. In a real task you already have
  // the placed instances; start at step 1 below.
  var level = Autodesk.Revit.DB.Level.Create(doc, 50.0);
  var wall = Autodesk.Revit.DB.Wall.Create(doc,
      Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(400, 0, 0), new Autodesk.Revit.DB.XYZ(410, 0, 0)),
      level.Id, false);
  doc.Regenerate();
  var group1 = doc.Create.NewGroup(new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId> { wall.Id });
  doc.Regenerate();
  var group2 = doc.Create.PlaceGroup(new Autodesk.Revit.DB.XYZ(400, 300, 0), group1.GroupType);
  doc.Regenerate();
  var group2Id = group2.Id;

  // 1. Ungroup the instance you want to change. Its members become ordinary
  //    loose elements with no group restrictions.
  var looseIds = group1.UngroupMembers();

  // 2. Edit the loose elements freely.
  Autodesk.Revit.DB.ElementId looseWallId = null;
  foreach (var id in looseIds) { if (doc.GetElement(id) is Autodesk.Revit.DB.Wall) looseWallId = id; }
  var lc = (doc.GetElement(looseWallId) as Autodesk.Revit.DB.Wall).Location as Autodesk.Revit.DB.LocationCurve;
  lc.Curve = Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(403, 0, 0), new Autodesk.Revit.DB.XYZ(413, 0, 0));
  doc.Regenerate();

  // 3. Regroup them: this mints a NEW GroupType that reflects the edit.
  var newGroup = doc.Create.NewGroup(new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId> { looseWallId });
  doc.Regenerate();
  var newType = newGroup.GroupType;

  // 4. Point every other placed instance at the new type. This is the
  //    propagation step: Group.GroupType has a public setter.
  var other = doc.GetElement(group2Id) as Autodesk.Revit.DB.Group;
  other.GroupType = newType;
  doc.Regenerate();

  // Revit re-creates the reassigned instance's members: re-fetch their ids.
  var memberIds = (doc.GetElement(group2Id) as Autodesk.Revit.DB.Group).GetMemberIds();
  return new { newGroupTypeId = newType.Id.Value, reassignedInstanceId = group2Id.Value, memberCount = memberIds.Count };
});
